const raw = $input.first().json;
const b = raw.body ?? raw;

const event = String(b.event || '').toLowerCase().trim();
const conv = b.conversation || b.message?.conversation || {};
const meta = conv.meta || b.meta || {};
const contact = meta.sender || b.sender || {};
const msg = b.message || (event === 'message_created' ? b : null);

function digits(v) {
  return String(v || '').replace(/\D/g, '');
}

let phone = digits(
  contact.phone_number || contact.phoneNumber || conv.phone_number,
);
if (!phone && contact.identifier) {
  phone = String(contact.identifier).split('@')[0].replace(/\D/g, '');
}
if (!phone && conv.contact_inbox?.source_id) {
  const sid = String(conv.contact_inbox.source_id);
  if (!sid.includes('-')) phone = digits(sid);
}

const inboxFilter = String($env.CHATWOOT_INBOX_ID || '').trim();
const inboxId = conv.inbox_id ?? conv.inbox?.id ?? b.inbox?.id;
if (inboxFilter && inboxId != null && String(inboxId) !== inboxFilter) {
  return [
    {
      json: {
        skip: true,
        reason: 'inbox_filtered',
        event,
        inboxId,
        phone: phone || null,
      },
    },
  ];
}

const assigneeId =
  conv.assignee_id ?? conv.assignee?.id ?? b.assignee?.id ?? null;
let status = String(conv.status || '').toLowerCase();

const changed = b.changed_attributes || conv.changed_attributes || [];
let assigneeChanged = false;
let statusChanged = false;
let currentAssignee = assigneeId;

for (const row of Array.isArray(changed) ? changed : []) {
  if (row.assignee_id) {
    assigneeChanged = true;
    currentAssignee = row.assignee_id.current_value ?? currentAssignee;
  }
  if (row.status) {
    statusChanged = true;
    status = String(row.status.current_value || status).toLowerCase();
  }
}

let mode = null;
let reason = null;

if (
  event === 'assignee_changed' ||
  (event === 'conversation_updated' && assigneeChanged)
) {
  if (currentAssignee) {
    mode = 'human';
    reason = 'chatwoot_assign';
  }
}

if (
  event === 'conversation_status_changed' ||
  (event === 'conversation_updated' && statusChanged)
) {
  if (status === 'resolved') {
    mode = 'bot';
    reason = 'chatwoot_resolved';
  } else if ((status === 'open' || status === 'pending') && currentAssignee) {
    mode = 'human';
    reason = 'chatwoot_status_' + status;
  }
}

if (event === 'message_created' && msg) {
  const senderType = String(
    msg.sender_type || msg.sender?.type || '',
  ).toLowerCase();
  const messageType = String(msg.message_type ?? '').toLowerCase();
  const sourceId = String(msg.source_id || '').trim();
  const externalSourceIds = msg.external_source_ids || {};
  const hasExternalSource =
    Boolean(sourceId) ||
    (typeof externalSourceIds === 'object' &&
      Object.keys(externalSourceIds).length > 0);
  const isOutgoing =
    messageType === 'outgoing' || messageType === '1' || msg.message_type === 1;

  // Mensagens da SofIA espelhadas pela Evolution aparecem como User/outgoing,
  // mas carregam source_id (ex.: WAID...). Mensagem digitada no painel não carrega.
  if (senderType === 'user' && isOutgoing && !hasExternalSource) {
    mode = 'human';
    reason = 'chatwoot_agent_message';
    const agentId = msg.sender_id ?? msg.sender?.id;
    if (agentId) currentAssignee = currentAssignee ?? agentId;
  }
}

const assigneeRef = currentAssignee
  ? `chatwoot-user-${currentAssignee}`
  : undefined;

const skip = !phone || phone.length < 10 || !mode;

return [
  {
    json: {
      event,
      phone,
      mode,
      reason,
      assigneeRef,
      conversationId: conv.id ?? null,
      status,
      assigneeId: currentAssignee,
      skip,
      debugSkipReason: skip
        ? !phone
          ? 'no_phone'
          : phone.length < 10
            ? 'phone_short'
            : 'no_mode_for_event'
        : null,
    },
  },
];
